                        guard let map=unwrapped as? [String: Any] else { return nil }
                        current=map[String(key)]
                    }
                    guard let node=current else { return nil }
                    return (node as? AnyCodable)?.value ?? node
                }
                for pair in pairs { if let nested=at(pair[0]) { guard let owner=at(pair[1]), same(nested,owner) else { return false } } }
            }
        }
        if let text=v as? String {
            let count=text.unicodeScalars.count
            if let min=s["minLength"] as? Int, count < min { return false }
            if let max=s["maxLength"] as? Int, count > max { return false }
            if let pattern=s["pattern"] as? String, text.range(of:pattern,options:.regularExpression) == nil { return false }
        }
        if let values=v as? [Any] {
            if let min=s["minItems"] as? Int, values.count < min { return false }
            if let max=s["maxItems"] as? Int, values.count > max { return false }
            if s["uniqueItems"] as? Bool == true { for i in values.indices { for j in values.indices where j < i { if same(values[i],values[j]) { return false } } } }
            if let item=s["items"] as? [String: Any], !values.allSatisfy({ matches(item,$0) }) { return false }
        }
        if let n=number, !isBoolean {
            if let min=s["minimum"] as? NSNumber, n.doubleValue < min.doubleValue { return false }
            if let max=s["maximum"] as? NSNumber, n.doubleValue > max.doubleValue { return false }
        }
        return true
    }
    static func timestamp(_ value: Date) -> String {
        let formatter=ISO8601DateFormatter()
        formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        return formatter.string(from:value)
    }
    static func field<T: Encodable>(_ value: T) throws -> Any {
        if let date=value as? Date { return timestamp(date) }
        let encoder=JSONEncoder(); encoder.dateEncodingStrategy = .iso8601
        return try JSONSerialization.jsonObject(with:encoder.encode(value),options:[.fragmentsAllowed])
    }
}
